def construct_spec(id_, title, subtitle, diff, minutes, kind, objective, description, organism, explore, construct, hints, done_title, summary, impact, case, context, simplify, steps, product, refs):
    return dict(id=id_, mode='construct', kind=kind, title=title, subtitle=subtitle, difficulty=diff, minutes=minutes, objective=objective, description=description,
                organism=organism, exploration=explore, construct=construct, product=product, steps=steps,
                hints=hints, done_title=done_title, summary=summary, impact=impact, case=case, context=context, simplify=simplify, refs=refs)

